import React, { useState } from 'react';
import Blobs  from '../components/Blobs';
import Orb3D  from '../components/Orb3D';
import { useMoods } from '../hooks/useStorage';

const MOODS = [
  { score:1, emoji:'😔', label:'Väldigt dåligt', colors:['#c04040','#601010','#e06060'] },
  { score:2, emoji:'😟', label:'Dåligt',         colors:['#b06020','#602010','#d08040'] },
  { score:3, emoji:'😐', label:'Okej',           colors:['#806040','#403020','#a08060'] },
  { score:4, emoji:'🙂', label:'Bra',            colors:['#406040','#204020','#60a060'] },
  { score:5, emoji:'😄', label:'Väldigt bra',    colors:['#4060c0','#202880','#6080e0'] },
];

export default function CheckIn({ setPage }) {
  const { addMood, todayChecked } = useMoods();
  const [selected, setSelected]   = useState(null);
  const [note, setNote]           = useState('');
  const [saved, setSaved]         = useState(false);

  const handleSave = () => {
    if (!selected) return;
    const m = MOODS.find(m => m.score === selected);
    addMood(m.score, m.emoji, m.label, note);
    setSaved(true);
  };

  if (saved || todayChecked) return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, textAlign:'center', padding:'0 24px', animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>
        <div style={{ display:'flex', justifyContent:'center', marginBottom:32 }}>
          <Orb3D size={160} colors={['#406040','#1a3010','#60a060']} speed={0.2} />
        </div>
        <h2 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', marginBottom:14 }}>
          {saved ? 'Incheckning sparad' : 'Redan incheckad'}
        </h2>
        <p style={{ fontSize:15, color:'rgba(255,255,255,0.4)', marginBottom:40, fontWeight:300, maxWidth:280, margin:'0 auto 40px' }}>
          {saved ? 'Bra att du tog en stund för dig själv.' : 'Kom tillbaka imorgon!'}
        </p>
        <div style={{ display:'flex', gap:12, justifyContent:'center', flexWrap:'wrap' }}>
          <button onClick={()=>setPage('history')} style={{ padding:'12px 24px', borderRadius:100, background:'rgba(255,255,255,0.9)', color:'#0a0a0f', fontSize:13, fontWeight:600 }}>Se historik</button>
          <button onClick={()=>setPage('home')} className="glass" style={{ padding:'12px 24px', borderRadius:100, color:'rgba(255,255,255,0.6)', fontSize:13 }}>Tillbaka</button>
        </div>
      </div>
    </div>
  );

  const selectedMood = MOODS.find(m => m.score === selected);

  return (
    <div style={{ minHeight:'100vh', position:'relative', display:'flex', alignItems:'center', justifyContent:'center' }}>
      <Blobs variant="calm" />
      <div style={{ position:'relative', zIndex:1, padding:'80px 24px 60px', width:'100%', maxWidth:480, animation:'fadeUp .7s cubic-bezier(0.16,1,0.3,1) both' }}>

        {/* Orb changes with mood selection */}
        <div style={{ display:'flex', justifyContent:'center', marginBottom:40, transition:'all .5s' }}>
          <Orb3D
            size={180}
            colors={selectedMood ? selectedMood.colors : ['#505080','#202040','#7070b0']}
            speed={0.3}
          />
        </div>

        <p style={{ fontFamily:'DM Mono,monospace', fontSize:10, letterSpacing:'0.2em', textTransform:'uppercase', color:'rgba(255,255,255,0.28)', marginBottom:14, textAlign:'center' }}>Daglig check-in</p>
        <h1 style={{ fontSize:'clamp(28px,6vw,44px)', fontWeight:700, letterSpacing:'-0.04em', color:'#fff', textAlign:'center', marginBottom:10, lineHeight:1 }}>Hur mår du idag?</h1>
        <p style={{ fontSize:13, color:'rgba(255,255,255,0.35)', textAlign:'center', marginBottom:40, fontWeight:300 }}>Tar bara 10 sekunder.</p>

        {/* Mood selector */}
        <div style={{ display:'flex', gap:8, justifyContent:'center', marginBottom:28, flexWrap:'wrap' }}>
          {MOODS.map(m => (
            <button key={m.score} onClick={()=>setSelected(m.score)} className="glass"
              style={{ display:'flex', flexDirection:'column', alignItems:'center', gap:6, padding:'16px 12px', minWidth:76, borderRadius:18, transform:selected===m.score?'translateY(-6px) scale(1.05)':'none', transition:'all .3s cubic-bezier(0.16,1,0.3,1)', border:`1px solid ${selected===m.score?'rgba(255,255,255,0.2)':'rgba(255,255,255,0.07)'}`, background:selected===m.score?'rgba(255,255,255,0.1)':'rgba(255,255,255,0.04)' }}>
              <span style={{ fontSize:28 }}>{m.emoji}</span>
              <span style={{ fontFamily:'DM Mono,monospace', fontSize:9, color:'rgba(255,255,255,0.4)', textAlign:'center', letterSpacing:'0.06em', lineHeight:1.3 }}>{m.label}</span>
            </button>
          ))}
        </div>

        {/* Note */}
        <div className="glass" style={{ borderRadius:16, padding:'16px', marginBottom:20 }}>
          <textarea value={note} onChange={e=>setNote(e.target.value)} maxLength={255}
            placeholder="Valfri notering om dagen..."
            style={{ width:'100%', background:'transparent', border:'none', color:'rgba(255,255,255,0.7)', fontSize:14, fontWeight:300, resize:'none', height:72, outline:'none' }}
            onFocus={e=>e.target.style.color='#fff'} onBlur={e=>e.target.style.color='rgba(255,255,255,0.7)'}
          />
        </div>

        <button onClick={handleSave} disabled={!selected}
          style={{ width:'100%', padding:'15px', borderRadius:100, background:selected?'rgba(255,255,255,0.92)':'rgba(255,255,255,0.07)', color:selected?'#0a0a0f':'rgba(255,255,255,0.2)', fontSize:14, fontWeight:600, transition:'all .3s' }}>
          Spara incheckning
        </button>
      </div>
    </div>
  );
}
